import java.text.DecimalFormat;
import java.util.Random;

public class DiceSimulator {

    public static void main(String[] args) {
        int[] simulations = {36, 500, 10000};
        DecimalFormat df = new DecimalFormat("#.####");

        // Calculate theoretical probabilities
        double[] theoreticalProbs = calculateTheoreticalProbabilities();

        Random rand = new Random();
        for (int numRolls : simulations) {
            System.out.println("\nSimulation with " + numRolls + " rolls:");
            int[] counts = new int[11]; // Array to store counts for sums 2 through 12

            // Simulate dice rolls
            for (int i = 0; i < numRolls; i++) {
                int roll = rand.nextInt(6) + rand.nextInt(6) + 2; // Roll two dice
                counts[roll - 2]++; // Increment count for the sum
            }

            // Display results
            displayResults(counts, theoreticalProbs, numRolls, df);
        }
    }

    private static double[] calculateTheoreticalProbabilities() {
        double[] theoreticalProbs = new double[11];
        for (int i = 2; i <= 12; i++) {
            // Number of ways to get each sum divided by total possible outcomes (36)
            int countWays = Math.min(i - 1, 13 - i) * 2 - (i == 7 ? 1 : 0);
            theoreticalProbs[i - 2] = (double) countWays / 36;
        }
        return theoreticalProbs;
    }

    private static void displayResults(int[] counts, double[] theoreticalProbs, int numRolls, DecimalFormat df) {
        System.out.println("Sum\tCount\tEm Prob\tP(X)");
        for (int i = 2; i <= 12; i++) {
            double emProb = (double) counts[i - 2] / numRolls;
            String formattedEmProb = df.format(emProb);
            String formattedTheoreticalProb = df.format(theoreticalProbs[i - 2]);
            System.out.printf("%d\t%d\t%.4f\t%.4f%n", i, counts[i - 2], Double.parseDouble(formattedEmProb), Double.parseDouble(formattedTheoreticalProb));
        }
    }
}
```
