```

Here's the complete C# code:

```csharp
using System;
using System.IO;
using SixLabors.ImageSharp;
using SixLabors.ImageSharp.Formats.Jpeg;
using SixLabors.ImageSharp.Formats.Png;
using SixLabors.ImageSharp.Processing;

public class ImageProcessor
{
    public static byte[] ConvertAndCompressImage(string image_path, string output_format, int width, int height, int? compression_level = null, int? quality = null)
    {
        using (var img = Image.Load(image_path))
        {
            // Resize the image to the specified dimensions
            img.Mutate(x => x.Resize(width, height));

            // Choose encoder based on the format
            var encoder = output_format.ToLower() switch
            {
                "jpeg" => new JpegEncoder { Quality = quality ?? 85 },
                "png" => new PngEncoder { CompressionLevel = compression_level ?? 9 },
                _ => throw new ArgumentException("Format must be either 'JPEG' or 'PNG'"),
            };

            // Save the image to a memory stream and get the byte array
            using (var memoryStream = new MemoryStream())
            {
                img.Save(memoryStream, encoder);
                return memoryStream.ToArray();
            }
        }
    }
}

class Program
{
    static void Main(string[] args)
    {
        // Example usage
        byte[] byte_array_jpeg = ImageProcessor.ConvertAndCompressImage("path/to/image.jpg", "JPEG", 800, 600, quality: 85);
        byte[] byte_array_png = ImageProcessor.ConvertAndCompressImage("path/to/image.png", "PNG", 800, 600, compression_level: 9);

        // Output the byte arrays for demonstration purposes
        Console.WriteLine($"JPEG byte array length: {byte_array_jpeg.Length}");
        Console.WriteLine($"PNG byte array length: {byte_array_png.Length}");
    }
}
```

### Explanation:
- **SixLabors.ImageSharp**: This library is used for image processing tasks, including resizing, compressing, and converting images.
- **Resizing the Image**: The `Mutate` method with `Resize` is used to adjust the image dimensions.
- **Compression/Quality Control**:
  - For PNG images, the `CompressionLevel` property controls the compression level. Higher values (0-9) mean more aggressive compression, resulting in smaller file sizes at the cost of increased processing time.
  - For JPEG images, the `Quality` property controls the trade-off between image quality and file size.
- **Saving to Byte Array**: The image is saved to a `MemoryStream`, and the resulting byte array is returned.

This implementation ensures that you can adjust the size and quality of both JPEG and PNG images according to your needs, taking into account the unique properties of each format.

