```python
def compute_first_sets(grammar):
    # Initialize the first sets for each non-terminal
    firsts = {symbol: set() for symbol in grammar}
    changed = True

    while changed:
        changed = False
        for symbol in grammar:
            for production in grammar[symbol]:
                if production[0].islower() or production[0] == '$':
                    if production[0] not in firsts[symbol]:
                        firsts[symbol].add(production[0])
                        changed = True
                elif production[0] != 'ε':
                    for token in production:
                        if 'ε' in firsts[token]:
                            firsts[symbol] |= firsts[token] - {'ε'}
                        else:
                            firsts[symbol] |= firsts[token]
                            break
                else:
                    if 'ε' not in firsts[symbol]:
                        firsts[symbol].add('ε')
                        changed = True

    return firsts

def compute_follow_sets(grammar, firsts):
    # Initialize the follow sets for each non-terminal
    follows = {symbol: set() for symbol in grammar}
    follows['S'].add('$')

    changed = True
    while changed:
        changed = False
        for symbol in grammar:
            for production in grammar[symbol]:
                for i, token in enumerate(production):
                    if token.isupper():
                        if i+1 < len(production):
                            first_next = firsts[production[i+1]]
                            if 'ε' in first_next:
                                follows[token] |= first_next - {'ε'}
                                follows[token] |= follows[symbol]
                            else:
                                follows[token] |= first_next
                        else:
                            follows[token] |= follows[symbol]
                        if 'ε' in firsts[token]:
                            follows[token] |= follows[symbol]
                            changed = True

    return follows

def build_ll1_table(grammar, firsts, follows):
    # Build the LL(1) parsing table
    table = {}
    for symbol in grammar:
        table[symbol] = {}
        for production in grammar[symbol]:
            for token in firsts[symbol]:
                if token != 'ε':
                    table[symbol][token] = production
            if 'ε' in firsts[symbol]:
                for token in follows[symbol]:
                    table[symbol][token] = production

    return table

# Extended Grammar with support for nested expressions, operator precedence, and multiple statements
grammar = {
    'S': ['<StatementList>'],
    'StatementList': ['<Statement> [";" <StatementList>]'],
    'Statement': ['<AssignmentExpression>', '<Expression>', '<LoopStatement>', '<SelectionStatement>', '<JumpStatement>', '<FunctionCall>'],
    'AssignmentExpression': ['<Variable> "=" <Expression>'],
    'Expression': ['<LogicalExpression>', '("(" <Expression> ")")'],
    'LogicalExpression': ['<LogicalExpression> "&&" <RelationalExpression>', '<LogicalExpression> "||" <RelationalExpression>', '<RelationalExpression>'],
    'RelationalExpression': ['<ArithmeticExpression> <RelationalOperator> <ArithmeticExpression>', '<ArithmeticExpression>'],
    'ArithmeticExpression': ['<Term> ["+" <Term> | "-" <Term>]'],
    'Term': ['<Factor> ["*" <Factor> | "/" <Factor>]'],
    'Factor': ['<Number>', '<Variable>', '("(" <Expression> ")")'],
    'LoopStatement': ['"for" "(" <Expression> ";" <Expression> ";" <Expression> ")" "{" <StatementList> "}"', '"while" "(" <Expression> ")" "{" <StatementList> "}"'],
    'SelectionStatement': ['"if" "(" <Expression> ")" "{" <StatementList> "}" ["else" "{" <StatementList> "}"]', '"switch" "(" <Expression> ")" "{" <CaseList> "default" ":" <StatementList> "}"'],
    'JumpStatement': ['"break"', '"continue"', '"return" <Expression>'],
    'FunctionCall': ['<Identifier> "(" <ArgumentList> ")"'],
    'CaseList': ['"case" <Expression> ":" <StatementList> ["case" <Expression> ":" <StatementList>]'],
    'ArgumentList': ['<Expression> ["," <Expression>]'],
    'Operator': ['"+"', '"-"', '"*"', '"/"'],
    'RelationalOperator': ['"<"', '">"', '"<="', '">="', '"=="', '"!="'],
    'Number': ['[0-9]+'],
    'Variable': ['[a-zA-Z][a-zA-Z0-9]*'],
    'Identifier': ['[a-zA-Z][a-zA-Z0-9]*']
}

# Compute First and Follow sets
firsts = compute_first_sets(grammar)
follows = compute_follow_sets(grammar, firsts)
ll1_table = build_ll1_table(grammar, firsts, follows)

print("First Sets:")
for key, value in firsts.items():
    print(f"{key}: {value}")

print("\nFollow Sets:")
for key, value in follows.items():
    print(f"{key}: {value}")

print("\nLL(1) Parsing Table:")
for key, value in ll1_table.items():
    print(f"{key}: {value}")

def parse(input_string, ll1_table):
    # Initialize the stack with the start symbol and the end-of-input marker
    stack = ['$']
    input_tokens = input_string.split()
    input_tokens.append('$')
    current_token_index = 0
    current_symbol = 'S'

    while True:
        current_token = input_tokens[current_token_index]

        if current_symbol == current_token:
            stack.pop()
            current_token_index += 1
            if current_token == '$':
                print("Parsing successful.")
                break
        elif current_symbol in ll1_table and current_token in ll1_table[current_symbol]:
            production = ll1_table[current_symbol][current_token]
            stack.pop()
            for symbol in reversed(production.split()):
                if symbol != 'ε':
                    stack.append(symbol)
        else:
            print(f"Parsing error: Expected one of {ll1_table[current_symbol].keys()} but found '{current_token}'")
            break

# Example parse
parse("x = 10; if (x > 5) { y = x + 1; } else { y = x - 1; }", ll1_table)
```

### Explanation:
1. **Grammar Rules**:
    - `S`: The start symbol, which represents a list of statements.
    - `StatementList`: A list of statements, optionally separated by semicolons.
    - `Statement`: Individual statements, including assignment, expression, loop, selection, jump, and function call.
    - `AssignmentExpression`, `Expression`, `LogicalExpression`, `RelationalExpression`, `ArithmeticExpression`, `Term`, `Factor`: Expressions with operator precedence and nesting support.
    - `LoopStatement`, `SelectionStatement`, `JumpStatement`, `FunctionCall`: Statements for loops, selections, jumps, and function calls.
    - `CaseList`, `ArgumentList`: Lists of cases and arguments, respectively.

2. **Parsing Table**: The LL(1) parsing table is built based on the computed First and Follow sets.

3. **Parsing Function**:
    - Initializes the stack with the start symbol and the end-of-input marker.
    - Iterates through the input tokens, matching them against the current symbol in the stack.
    - Uses the LL(1) table to determine the next action, either reducing the stack by applying a production rule or popping a token.
    - Handles parsing errors by indicating the expected tokens and the actual token that caused the error.

This setup ensures that the parser can handle nested expressions, operator precedence, and multiple statements, following standard C language rules.

