% Load the image
originalImage = imread('saturn.tif');

% Function to perform degradation
function degradedImage = degradeImage(image, noiseLevel)
    % Compute the Fourier transform
    x = fft2(double(image));
    % Add noise to specific frequency components
    x(10,10) = x(10,10) + noiseLevel;
    x(10,11) = x(10,11) + noiseLevel;
    x(11,10) = x(11,10) + noiseLevel;
    x(11,11) = x(11,11) + noiseLevel;
    % Inverse Fourier transform to get the degraded image
    degradedImage = real(ifft2(x));
end

% Function to restore image using Total Variation regularization
function restoredImage = restoreImageTV(degradedImage, weight)
    % Use Total Variation regularization for restoration
    restoredImage = imregionalmax(degradedImage, weight);
end

% Degradation
