         NoiseSettings noiseSettings = new NoiseSettings();
         noiseSettings.Octaves = 6;
         noiseSettings.Persistence = 0.5f;
         noiseSettings.Lacunarity = 2.0f;
         noiseSettings.Scale = 0.05f;

         // Generate heightmap using noise functions
         float[,] heightMap = Vista2023API.GenerateHeightMap(x, y, noiseSettings);

         // Create and apply the heightmap to the terrain chunk
